// Generates src/generated/*.ts from the frozen backend OpenAPI 3.1 specs.
//   node scripts/generate.mjs           vendor specs from ../RSVPBackend (if present) and regenerate
//   node scripts/generate.mjs --check   fail if generated files differ from the vendored specs, or the vendored
//                                        specs differ from the backend checkout (when it is present)
import { createHash } from 'node:crypto';
import { existsSync } from 'node:fs';
import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const vendored = join(root, 'specs');
const generated = join(root, 'src', 'generated');
const backend = process.env.RSVP_BACKEND_SPECS ?? join(root, '..', '..', '..', 'RSVPBackend', 'packages', 'contracts-openapi', 'specs');
const check = process.argv.includes('--check');
const banner = '// GENERATED by packages/contracts/scripts/generate.mjs from the frozen backend OpenAPI specs. Do not edit.\n';
const sha = (text) => createHash('sha256').update(text).digest('hex');
const names = (files) => files.filter((f) => f.endsWith('.openapi.json')).map((f) => f.replace('.openapi.json', '')).sort();

const problems = [];
const backendPresent = existsSync(backend);
if (!backendPresent) console.warn(`[contracts] backend specs not found at ${backend}; using vendored snapshot.`);

if (backendPresent) {
  for (const name of names(await readdir(backend))) {
    const source = await readFile(join(backend, `${name}.openapi.json`), 'utf8');
    const target = join(vendored, `${name}.openapi.json`);
    const current = existsSync(target) ? await readFile(target, 'utf8') : undefined;
    if (current !== source) {
      if (check) problems.push(`specs/${name}.openapi.json differs from the backend: run "yarn workspace @rsvp/contracts generate"`);
      else await writeFile(target, source);
    }
  }
}

const specNames = names(await readdir(vendored));
if (specNames.length === 0) throw new Error('No OpenAPI specs vendored.');
if (!check) await mkdir(generated, { recursive: true });
const manifest = {};
for (const name of specNames) {
  const text = await readFile(join(vendored, `${name}.openapi.json`), 'utf8');
  const ast = await openapiTS(JSON.parse(text), { alphabetize: true });
  const output = banner + astToString(ast);
  manifest[name] = sha(text).slice(0, 16);
  const file = join(generated, `${name}.ts`);
  if (check) {
    const current = existsSync(file) ? await readFile(file, 'utf8') : undefined;
    if (current !== output) problems.push(`src/generated/${name}.ts is stale: run "yarn workspace @rsvp/contracts generate"`);
  } else await writeFile(file, output);
}
const camel = (name) => name.split('-').map((p, i) => (i ? p[0].toUpperCase() + p.slice(1) : p)).join('');
const pascal = (name) => { const c = camel(name); return c[0].toUpperCase() + c.slice(1); };
const index = banner + specNames.map((n) => `export type { paths as ${pascal(n)}Paths, components as ${pascal(n)}Components, operations as ${pascal(n)}Operations } from './${n}.js';`).join('\n') + `\n\nexport const contractVersions = ${JSON.stringify(manifest, null, 2)} as const;\n`;
const indexFile = join(generated, 'index.ts');
if (check) {
  const current = existsSync(indexFile) ? await readFile(indexFile, 'utf8') : undefined;
  if (current !== index) problems.push('src/generated/index.ts is stale');
} else await writeFile(indexFile, index);

if (problems.length) { console.error(problems.join('\n')); process.exit(1); }
console.log(`[contracts] ${check ? 'verified' : 'generated'} ${specNames.length} contracts: ${specNames.join(', ')}`);
